xpath.script:
(function () {
  if (!window.Element || !Element.prototype.attachShadow) {
    return;
  }

  var originalAttachShadow = Element.prototype.attachShadow;

  Element.prototype.attachShadow = function (init) {
    var className = typeof this.className === 'string' ? this.className : '';
    var elementId = this.id || '';
   var isElfsightHost =
   className.indexOf('elfsight-app-') !== -1 ||
   className.indexOf('eapps-') !== -1 ||
   className.indexOf('es-embed-root') !== -1 ||
   elementId.indexOf('elfsight') !== -1 ||elementId.indexOf('eapps') !== -1;

    if (!isElfsightHost) {
      return originalAttachShadow.call(this, init);
    }

    var root = originalAttachShadow.call(
      this,
      Object.assign({}, init, { mode: 'open' })
    );

    function removeBadge() {
      root.querySelectorAll(
        'a[href*="elfsight.com/testimonials-slider-widget"], ' +
        'a[href*="testimonials-slider-widget"]'
      ).forEach(function (element) {
        element.remove();
      });
    }

    removeBadge();

    new MutationObserver(removeBadge).observe(root, {
      childList: true,
      subtree: true
    });

    return root;
  };
})();
